import hashlib,json,os,signal,subprocess
from pathlib import Path
p=Path(__file__).parent
load=lambda f:json.loads(Path(f).read_text())
sha=lambda f:hashlib.sha256(Path(f).read_bytes()).hexdigest()
os.sched_setaffinity(0,{0})
plan={'stages':['optimize','physical'],'order':['before','after','after','before'],'samples':4097,'warmups':32,'event':'instructions:u','period':100003,'case':'generic_in_double_zero_single','stack_capture':False,'limit':'Self instruction samples only; stage gates add work. No inference about elapsed time.'}
q=p/'profiles-lowrate';q.mkdir()
(q/'plan.json').write_text(json.dumps(plan,indent=2)+'\n')
canonical={v:{r['id']:r for r in load(p/f'old-{v}-check.json')['results']} for v in ['before','after']}
hashes={v:sha(p/f'{v}-bench') for v in ['before','after']}
runs=[]
for stage in plan['stages']:
 for i,v in enumerate(plan['order']):
  d=q/f'{stage}-{i}-{v}';d.mkdir()
  for name in ['control','ack']:os.mkfifo(d/name)
  command=['perf','record','--delay=-1',f'--control=fifo:{d}/control,{d}/ack','-e',plan['event'],'-c',str(plan['period']),'--no-buildid-cache','-m','64','-o',str(d/'perf.data'),'--','taskset','-c','2',str(p/f'{v}-bench'),str(d/'capture.json'),'generic-in',plan['case']]
  env={k:os.environ[k] for k in ['PATH','LANG','LC_ALL','TZ'] if k in os.environ}
  env.update({'DECIMAL_BENCH_PERF_DIR':str(d),'DECIMAL_BENCH_PERF_PHASE':'planning','DECIMAL_BENCH_PLAN_STAGE':stage,'DECIMAL_BENCH_IN_WARMUPS':str(plan['warmups']),'DECIMAL_BENCH_IN_SAMPLES':str(plan['samples'])})
  with subprocess.Popen(command,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True) as process:
   try:stdout,stderr=process.communicate(timeout=60)
   except subprocess.TimeoutExpired:
    os.killpg(process.pid,signal.SIGKILL);stdout,stderr=process.communicate()
    (d/'failure.json').write_text(json.dumps({'error':'Own stage profiler timed out','stdout':stdout,'stderr':stderr})+'\n');raise
  (d/'stdout.txt').write_text(stdout);(d/'stderr.txt').write_text(stderr)
  assert process.returncode==0,(v,stderr)
  assert stderr.count('Events enabled')==plan['samples'],stderr.count('Events enabled')
  capture=load(d/'capture.json');assert capture['plan_stage']==stage and capture['samples']==plan['samples'] and capture['warmups']==plan['warmups']
  for row in capture['results']:assert all(row[k]==val for k,val in canonical[v][row['id']].items())
  runs.append({'stage':stage,'index':i,'variant':v,'binary_sha256':hashes[v],'command':command,'environment_overrides':env,'capture_sha256':sha(d/'capture.json'),'perf_data_sha256':sha(d/'perf.data'),'perf_data_bytes':(d/'perf.data').stat().st_size,'capture':capture,'stderr':stderr})
  (q/'profiles.json').write_text(json.dumps(runs,indent=2)+'\n')
  print(stage,i,v,'complete',flush=True)

